// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title AccessControlledVault
/// @notice Multi-tier vault with role-based access via gRPC proxy metadata
/// @dev The gRPC reverse proxy forwards authenticated user context as calldata suffix

contract AccessControlledVault {
    enum Role { NONE, VIEWER, OPERATOR, ADMIN }

    struct UserContext {
        address account;
        Role role;
        uint256 sessionExpiry;
        bytes32 proxyAttestation;
    }

    mapping(address => Role) public roles;
    mapping(address => uint256) public balances;
    mapping(bytes32 => bool) public usedAttestations;

    address public immutable proxyAddress;
    bytes32 public immutable proxySecret;
    uint256 public totalDeposits;

    event Withdrawal(address indexed account, uint256 amount);
    event RoleChanged(address indexed account, Role newRole);
    event AdminAction(address indexed admin, bytes32 actionHash);

    modifier onlyProxy() {
        require(msg.sender == proxyAddress, "Only proxy");
        _;
    }

    constructor(address _proxy, bytes32 _secret) {
        proxyAddress = _proxy;
        proxySecret = _secret;
        roles[msg.sender] = Role.ADMIN;
    }

    /// @notice Extracts user context from proxy-appended calldata
    /// @dev The gRPC proxy appends 128 bytes: [address(20) | role(32) | expiry(32) | attestation(32)]
    function _extractContext() internal view returns (UserContext memory ctx) {
        require(msg.data.length >= 128 + 4, "Invalid context");

        uint256 offset = msg.data.length - 116;

        bytes32 rawAddr;
        assembly {
            rawAddr := calldataload(offset)
        }
        ctx.account = address(uint160(uint256(rawAddr)));

        assembly {
            let roleVal := calldataload(add(offset, 20))
            mstore(add(ctx, 0x20), roleVal)
        }

        assembly {
            let expiryVal := calldataload(add(offset, 52))
            mstore(add(ctx, 0x40), expiryVal)
        }

        assembly {
            let attestVal := calldataload(add(offset, 84))
            mstore(add(ctx, 0x60), attestVal)
        }

        return ctx;
    }

    /// @notice Validates the proxy attestation to prevent context forgery
    function _validateAttestation(UserContext memory ctx) internal view returns (bool) {
        bytes32 expected = keccak256(
            abi.encodePacked(ctx.account, ctx.role, ctx.sessionExpiry, proxySecret)
        );
        return ctx.proxyAttestation == expected;
    }

    /// @notice Validates session hasn't expired
    function _validateSession(UserContext memory ctx) internal view returns (bool) {
        return block.timestamp <= ctx.sessionExpiry;
    }

    /// @notice Combined authorization check
    function _authorize(Role minimumRole) internal view returns (UserContext memory) {
        UserContext memory ctx = _extractContext();

        require(_validateSession(ctx), "Session expired");
        require(_validateAttestation(ctx), "Invalid attestation");

        // Role hierarchy check: user's on-chain role must meet minimum
        Role onChainRole = roles[ctx.account];
        require(uint8(onChainRole) >= uint8(minimumRole), "Insufficient role");

        return ctx;
    }

    /// @notice Deposit funds - available to OPERATOR and above
    function deposit() external payable onlyProxy {
        UserContext memory ctx = _authorize(Role.OPERATOR);
        balances[ctx.account] += msg.value;
        totalDeposits += msg.value;
    }

    /// @notice Withdraw funds - available to OPERATOR and above
    function withdraw(uint256 amount) external onlyProxy {
        UserContext memory ctx = _authorize(Role.OPERATOR);
        require(balances[ctx.account] >= amount, "Insufficient balance");

        balances[ctx.account] -= amount;
        totalDeposits -= amount;

        (bool success, ) = ctx.account.call{value: amount}("");
        require(success, "Transfer failed");
        emit Withdrawal(ctx.account, amount);
    }

    /// @notice Admin-only: change user roles
    function setRole(address account, Role newRole) external onlyProxy {
        UserContext memory ctx = _authorize(Role.ADMIN);
        require(account != ctx.account, "Cannot change own role");
        roles[account] = newRole;
        emit RoleChanged(account, newRole);
    }

    /// @notice Admin-only: emergency drain
    function emergencyDrain(address payable recipient) external onlyProxy {
        UserContext memory ctx = _authorize(Role.ADMIN);
        bytes32 actionHash = keccak256(abi.encodePacked("drain", recipient, block.number));
        require(!usedAttestations[ctx.proxyAttestation], "Attestation replay");
        usedAttestations[ctx.proxyAttestation] = true;

        uint256 bal = address(this).balance;
        (bool success, ) = recipient.call{value: bal}("");
        require(success, "Transfer failed");
        emit AdminAction(ctx.account, actionHash);
    }

    /// @notice View balance - available to VIEWER and above
    function getBalance(address account) external view returns (uint256) {
        // No proxy requirement for view functions
        return balances[account];
    }

    receive() external payable {}
}
